// @ppm--dependency--config.cfimages-repo
// @ppm--dependency--config.image-sync-worker-key


import { useEffect, useState } from "react";
import React from "react";
import { useImageSyncQueue } from "../../../ppm/cfimages/useImageSyncQueue";
import { getToken } from "../../../ppm/openbase/openbase";
import { IMAGE_SYNC_QUEUE } from "../../../ppm/config/image-sync-worker-key";
import { CF_IMAGES_REPO } from "../../../ppm/config/cfimages-repo";
import { CF_IMAGES_WORKER } from "../../../ppm/config/cfimages-worker-url";
const FILES_JSON_URL : string = `${CF_IMAGES_REPO}/images/files.json`
const CFIMAGE_WORKER_UPDATE_IMAGE =  `${CF_IMAGES_WORKER}/api/update-image`;



type FileRow = {
  id: string;
  path: string;
  name: string;
  meta?: Record<string, any>;
};

type FilesJson = Record<
  string,
  {
    path: string;
    name: string;
    meta?: Record<string, any>;
  }
>;

export default function TestImageTable() {
  const [rows, setRows] = useState<FileRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>("");
  const [deletingId, setDeletingId] = useState<string>("");
  const [lockUI, setLockUI] = useState(false);

  const { reconcile, queueDelete } = useImageSyncQueue();

  const btnStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    background: "#fff",
    borderRadius: 8,
    padding: "6px 10px",
    cursor: "pointer",
  };

  const formatDate = (id: string) => {
    const timestamp = Number(String(id).split("-")[0]);
    if (!Number.isFinite(timestamp)) return "-";
    const date = new Date(timestamp);
    if (Number.isNaN(date.getTime())) return "-";

    return new Intl.DateTimeFormat("en-US", {
      month: "2-digit",
      day: "2-digit",
      year: "numeric",
    }).format(date);
  };

  const loadFiles = async () => {
    setLoading(true);
    setError("");

    try {
      const res = await fetch(`${FILES_JSON_URL}?v=${Date.now()}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const json: FilesJson = await res.json();

      const parsed: FileRow[] = Object.entries(json || {}).map(([id, value]) => ({
        id,
        path: value?.path || "",
        name: value?.name || "",
        meta: value?.meta || {},
      }));

      parsed.sort((a, b) => {
        const aTime = Number(String(a.id).split("-")[0]);
        const bTime = Number(String(b.id).split("-")[0]);
        return bTime - aTime;
      });

      const { filteredRows } = reconcile(parsed);
      setRows(filteredRows);
    } catch (err: any) {
      setError(err?.message || "Failed to load");
    } finally {
      setLoading(false);
    }
  };

  const sendChanges = async (changes: any[]) => {
    const token = getToken();
    if (!token) throw new Error("No auth token");

    const res = await fetch(CFIMAGE_WORKER_UPDATE_IMAGE, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ changes }),
    });

    const text = await res.text();
    let json: any = null;
    try { json = JSON.parse(text); } catch {}

    if (!res.ok) {
      throw new Error(json?.error || text || "Update failed");
    }
  };

  const handleDelete = async (row: FileRow) => {
    if (!window.confirm(`Delete ${row.name}?`)) return;

    setDeletingId(row.id);
    setLockUI(true);
    setError("");

    queueDelete(row.id);
    setRows((prev) => prev.filter((r) => r.id !== row.id));

    try {
      await sendChanges([{ action: "delete", id: row.id }]);
    } catch (err: any) {
      setError(err?.message);
      setRows((prev) => [row, ...prev]);
    } finally {
      await new Promise((r) => setTimeout(r, 2000));
      setDeletingId("");
      setLockUI(false);
    }
  };

  const handleRename = async (row: FileRow) => {
    const newName = prompt("New filename (.webp):", row.name);
    if (!newName) return;

    setLockUI(true);
    setError("");

    try {
      await sendChanges([
        { action: "rename", id: row.id, value: newName },
      ]);
      await loadFiles();
    } catch (err: any) {
      setError(err?.message);
    } finally {
      setLockUI(false);
    }
  };

  const handleUpdateMeta = async (row: FileRow) => {
    const alt = prompt("Alt text:", row.meta?.alt || "");
    if (alt === null) return;

    setLockUI(true);
    setError("");

    try {
      await sendChanges([
        {
          action: "update",
          id: row.id,
          attribute: "meta",
          value: {
            ...(row.meta || {}),
            alt,
          },
        },
      ]);
      await loadFiles();
    } catch (err: any) {
      setError(err?.message);
    } finally {
      setLockUI(false);
    }
  };

  useEffect(() => {
    loadFiles();
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h2>Images</h2>

      {loading ? (
        "Loading..."
      ) : error ? (
        <div style={{ color: "red" }}>{error}</div>
      ) : (
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Preview</th>
              <th>Date</th>
              <th>Name</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {rows.map((row, i) => (
              <tr key={row.id}>
                <td>{i + 1}</td>

                <td>
                  <img src={row.path} width={80} />
                </td>

                <td>{formatDate(row.id)}</td>

                <td>{row.name}</td>

                <td style={{ display: "flex", gap: 8 }}>
                  <button style={btnStyle} onClick={() => handleRename(row)}>
                    Rename
                  </button>

                  <button style={btnStyle} onClick={() => handleUpdateMeta(row)}>
                    Meta
                  </button>

                  <button style={btnStyle} onClick={() => handleDelete(row)}>
                    {deletingId === row.id ? "..." : "Delete"}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {lockUI && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.4)",
          }}
        />
      )}

      <button
        style={{ ...btnStyle, marginTop: 20 }}
        onClick={() => {
          const data = JSON.parse(
            localStorage.getItem(IMAGE_SYNC_QUEUE) || "{}"
          );
          console.log("QUEUE:", data);
            alert('check console')
        }}
      >
        Debug Queue
      </button>


      <button
        style={{ ...btnStyle, marginTop: 20 }}
        onClick={() => {
          localStorage.setItem(IMAGE_SYNC_QUEUE,  JSON.stringify({}));
          alert('done')
        }}
      >
        Delete Queue
      </button>


    </div>
  );
}